D, DET, CH, CPU, REG, RC = J("rk11_distribution.json"), J("rk11_determinism.json"), J("rk11_chrome_node.json"), J("rk11_cpu.json"), J("rk11_regression.json"), J("receive11_matrix_714_rerun_compare.json")
