S = {"milestone": "RECEIVE-KILL-1.1", "date": "2026-10-18", "branch": "prototype/dribble-1", "frozen": False, "constantsLocked": False, "integratedIntoReceiveControl11": False,
  "readyToFreeze": "NO — presented for the owner's visual review ('Do NOT freeze the constants automatically. I want to visually review the compressed scale.')",
  "model": {"old": "E = 0.0068 + 0.40 · u^1.1 · D/(D+1)", "new": "E = 0.0068 + 0.25 · u·(0.68 + 0.32·u²) · D/(D+1); chest k [0.85,0.5,0.5], head k [0.85,0.7,0.5]", "constants": D["RK"]},
  "followUp": "after THIGH / CHEST / HEAD always, after a foot kill when the ball will not settle by itself; a foot control (sole / instep / inside) planned on the kernel's prediction of the real post-contact ball; at most 3 contacts; each contact one authoritative schedule()",
  "distribution": {"incomingBalls": sum(len(r) for r in D["matrices"].values()), "ratings": D["bc"], "seeds": D["nSeeds"], "wallSeconds": round(D["ms"] / 1000, 1)}, "benchmarks": bench,
  "determinism": {"drawsIdenticalAcrossBC": f'{DET["matched"]["drawsIdenticalAcrossBC"]}/{DET["matched"]["drawsChecked"]}', "firstContactProportional": f'{DET["matched"]["proportional"]}/{DET["matched"]["proportionalChecked"]}', "replay": f'{DET["replay"]["identical"]}/{DET["replay"]["runs"]}', "schedulePath": f'{DET["schedulePath"]["identical"]}/{DET["schedulePath"]["runs"]}', "animationOnOff": f'{DET["anim"]["identical"]}/{DET["anim"]["runs"]}', "chromeNode": f'{CH["identical"]}/{CH["total"]}'},
  "cpu": {g: {"firstContactMs": round(c["firstContactMs"], 4), "wholeEpisodeMs": round(c["wholeEpisodeMs"], 3), "worstEpisodeMs": round(c["worstEpisodeMs"], 3)} for g, c in CPU["groups"].items()},
  "regression": {"receiveKill1Cells": f'{REG["kill1MatchEvidenceAfter"]}/{REG["kill1Cells"]}', "dribbleV1": f'{REG["dribbleBeforeEqualsAfter"]}/{REG["dribbleRuns"]}', "dribbleV1Evidence": f'{REG["dribbleEvidenceMatch"]}/{REG["dribbleEvidenceCompared"]}', "receive11Cases": f'{REG["receive11BeforeEqualsAfter"]}/{REG["receive11Cases"]}', "receive11Matrix": f'{RC["identical"]}/{RC["runs"]}', "frozenParamsUnchanged": REG["frozenParamsUnchanged"], "frozenFiles": "IDENTICAL" if "IDENTICAL" in open(os.path.join(EV, "frozen_sha256_end_check.txt")).read() else "CHANGED"},
  "limitations": ["placeholder body, not in the ball's world", "stationary receiver in clean conditions; adjustment speed and foot timing fixed (Agility / Dribbling later)", "hard aerial balls at low ratings still produce loose balls (forced 15 m/s header the extreme)", "follow-ups are foot controls only", "constants not locked"],
  "review": "review/RECEIVE_KILL11_REVIEW.html (local only)"}
